function t(key){
  /* Dil durumu ilk çizimden önce de hazır olsun. Bazı modüller (özellikle
     Notlarım/Yazma Pratiği) ayrı script olarak yüklenir; yalnızca
     setLangPair() sonrasındaki window değerine güvenmek, ilk açılışta veya
     dil değişimi sırasında kısa süreli Türkçe/İngilizce karışmasına yol
     açabiliyordu. */
  var lang = window.NATIVE_LANG || (typeof NATIVE_LANG !== 'undefined' ? NATIVE_LANG : 'tr');
  var dict = I18N[lang] || I18N.tr;
  var v = (dict && Object.prototype.hasOwnProperty.call(dict,key)) ? dict[key] : undefined;
  if(v===undefined) v = (I18N.tr && I18N.tr[key]);
  if(typeof v==='string'&&v.includes('{vocabTotal}'))v=v.replaceAll('{vocabTotal}',Number(window.LUMIRA_CATALOG?.total||0).toLocaleString(lang));
  return (v===undefined) ? key : v;
}
window.t = t; window.I18N = I18N;for(const node of document.querySelectorAll('[data-vocab-total]'))node.textContent=Number(window.LUMIRA_CATALOG?.total||0).toLocaleString(window.NATIVE_LANG||'tr');
